/* From Uiverse.io by liyaxu123 - Tags: input, animated */
.__UIV_SCOPE__ .form-control {
  position: relative;
  margin: 20px 0 40px;
  width: 190px;
}

.__UIV_SCOPE__ .form-control input {
  background-color: transparent;
  border: 0;
  border-bottom: 2px #fff solid;
  display: block;
  width: 100%;
  padding: 15px 0;
  font-size: 18px;
  color: #fff;
}

.__UIV_SCOPE__ .form-control input:focus,
.__UIV_SCOPE__ .form-control input:valid {
  outline: 0;
  border-bottom-color: lightblue;
}

.__UIV_SCOPE__ .form-control label {
  position: absolute;
  top: 15px;
  left: 0;
  pointer-events: none;
}

.__UIV_SCOPE__ .form-control label span {
  display: inline-block;
  font-size: 18px;
  min-width: 5px;
  color: #fff;
  transition: 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.__UIV_SCOPE__ .form-control input:focus+label span,
.__UIV_SCOPE__ .form-control input:valid+label span {
  color: lightblue;
  transform: translateY(-30px);
}
